package it.servizidigitali.gestionebandi.model;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public enum DatoAggiuntivoChiave {
    TIPOLOGIA_SOGGETTO("$.schema.properties.formaCandidatura", "$.alpaca.data.formaCandidatura", "tipologiaSoggetto", 1),
    DATA_CONFERMA_EVENTO("","","",2),
    FORM_ESECUZIONE_NON_ABILITATO("$.schema.properties.soggettoProponentePresenta.properties.campoDaEscludere", "$.alpaca.data.soggettoProponentePresenta.campoDaEscludere", "", 0),
    DISABILITA_FORM_ESECUZIONE("", "", "", 0),
    CIVICO_SEDE_LEGALE_ENTE("$.schema.properties.sedeLegale.properties.civico","$.alpaca.data.sedeLegale.civico","",0),
    INDIRIZZO_SEDE_LEGALE_ENTE("$.schema.properties.sedeLegale.properties.indirizzoSedeLegale","$.alpaca.data.sedeLegale.indirizzoSedeLegale","",0),
    CITTA_SEDE_LEGALE("$.schema.properties.sedeLegale.properties.provinciaComuneSedeLegale.properties.denominazioneComune","$.alpaca.data.sedeLegale.provinciaComuneSedeLegale.denominazioneComune","",0),
    PROVINCIA_SEDE_LEGALE_ENTE("$.schema.properties.sedeLegale.properties.provinciaComuneSedeLegale.properties.provincia","$.alpaca.data.sedeLegale.provinciaComuneSedeLegale.provincia","",0),
    CAP_SEDE_LEGALE("$.schema.properties.sedeLegale.properties.cap","$.alpaca.data.sedeLegale.cap","",0),
    TITOLO_PROGRAMMA_TRIENNALE("$.schema.properties.titoloProgrammaTriennale","$.alpaca.data.titoloProgrammaTriennale","",0),
    PEC_RICHIEDENTE("$.schema.properties.pecRichiedente","$.alpaca.data.pecRichiedente","pecRichiedente",0),
    CF_ENTE("","","",0),
    DATA_INIZIO_UPLOAD_DOCUMENTI("","","",0),
    DATA_FINE_UPLOAD_DOCUMENTI("","","",0),
    TIPOLOGIA_ENTE("","","",0),
    CHIUSURA_NEGATIVA_AUTOMATICA("","","",0),
    NOTE_CHIUSURA_NEGATIVA("","","",0),
    IMPORTO_REVOCATO("","","",0),
    PUNTEGGIO_AUTOVALUTAZIONE("","","",0),
    IMPRONTA_ISTANZA("","","",0);

    private final String schemaJsonPath;
    private final String dataJsonPath;
    private final String excelLabel;
    private final int numeroOrdine;

    private DatoAggiuntivoChiave(String schemaJsonPath, String dataJsonPath, String excelLabel, int numeroOrdine) {
        this.schemaJsonPath = schemaJsonPath;
        this.dataJsonPath = dataJsonPath;
        this.excelLabel = excelLabel;
        this.numeroOrdine = numeroOrdine;
    }
    public String getExcelLabel() {
        return excelLabel;
    }
    public String getSchemaJsonPath() {
        return schemaJsonPath;
    }
    public String getDataJsonPath() {
        return dataJsonPath;
    }
    public int getNumeroOrdine() {
        return numeroOrdine;
    }

    public static List<DatoAggiuntivoChiave> getChiaviConExcelLabel() {
        return Arrays.stream(values())
            .filter(d -> d.excelLabel != null && !d.excelLabel.isEmpty())
            .collect(Collectors.toList());
    }
}

