private String getTaskId(DomandaBando domandaBando) {
    List<Task> tasks = camundaClient.searchTasks(domandaBando.getProcessInstanceId());
    if (tasks.isEmpty()) {
        throw new RuntimeException("No task");
    }

    if (tasks.size() > 1) {
        log.warn("Piu task per processo " + domandaBando.getProcessInstanceId());
    }

    return tasks.get(0).getId();
}

public void annullaDomandaBando(ServiceContext serviceContext, long domandaBandoId, long allegatoAnnullamentoId) {

    try {
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

        String taskId = getTaskId(domandaBando);

        String tenantId = String.valueOf(serviceContext.getScopeGroup().getOrganizationId());
        List<Task> tasksByBusinessKey = camundaClient.getTasksByBusinessKey(tenantId,
                String.valueOf(domandaBandoId));

        if (tasksByBusinessKey != null) {

            for (Task task : tasksByBusinessKey) {
                if (taskId.equalsIgnoreCase(task.getId())) {
                    List<Map.Entry<String, Object>> variables = new ArrayList<>();

                    // TODO: Capire se questi valori devono rimanere hard coded

                    variables.add(new AbstractMap.SimpleEntry<>("ESITO_PROCEDIMENTO", "ANNULLAMENTO"));
                    variables.add(new AbstractMap.SimpleEntry<>("COMUNICAZIONE_ESITO", "SI"));
                    variables.add(new AbstractMap.SimpleEntry<>("ID_ALLEGATO_ANNULLAMENTO",
                            String.valueOf(allegatoAnnullamentoId)));

                    camundaClient.completeTaskMultiType(taskId, variables);
                }
            }
        }

    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

public JsonObject enrichFormIntegrativoAnnullamentoBandi(JsonObject alpacaJsonData,
                                                         AlpacaJsonOptionsStructure optionsStr, IstanzaDomandaBando istanzaDomandaBando) {
    DomandaBando domandaBando = null;
    Bando bando = null;
    try {
        domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
        bando = bandoLocalService.getBando(domandaBando.getBandoId());
    } catch (PortalException e) {
        // TODO Auto-generated catch block
        e.printStackTrace();
    }
    List<String> fieldNamesDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr,
            typesPraticaDaAnnullare);
    if (fieldNamesDataContainer != null && domandaBando != null && bando != null) {
        for (String fieldNameDataContainer : fieldNamesDataContainer) {
            JsonObject fieldDataContainer = alpacaJsonData.getAsJsonObject(fieldNameDataContainer);
            if (fieldDataContainer != null) {

                String placeholderAnnullamentoPratica = "Chiede di annullare ";
                TipologiaBando tipologiaBando = tipologiaBandoLocalService
                        .fetchTipologiaBando(bando.getTipologiaBandoId());
                if (Validator.isNotNull(tipologiaBando)) {
                    if (tipologiaBando.getCodice().equalsIgnoreCase(TipologiaBandoEnum.EVENTO.name())) {
                        placeholderAnnullamentoPratica += "l'istanza con ID: <b>%s</b>, appartenente all'Evento: <b>%s</b>";
                    } else {
                        placeholderAnnullamentoPratica += "la Domanda Bando con ID: <b>%s</b>, appartenente al Bando: <b>%s</b>";
                    }
                } else {
                    placeholderAnnullamentoPratica += "la Domanda Bando con ID: <b>%s</b>, appartenente al Bando: <b>%s</b>";
                }
                String note = String.format(placeholderAnnullamentoPratica, domandaBando.getDomandaBandoId(),
                        bando.getNome());

                fieldDataContainer.addProperty("note", note);

                alpacaJsonData.add(fieldNameDataContainer, fieldDataContainer);
            }
        }
        // Salvo

    }

    return alpacaJsonData;
}

public JsonObject enrichCronoprogramma(JsonObject alpacaJsonData, AlpacaJsonOptionsStructure optionsStr,
                                       JsonObject cronoprogrammaArray) {

    List<String> fieldNamesDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr,
            typesCronoprogrammaBandi);
    if (fieldNamesDataContainer != null) {
        for (String fieldNameDataContainer : fieldNamesDataContainer) {
            JsonObject fieldDataContainer = alpacaJsonData.getAsJsonObject(fieldNameDataContainer);
            if (fieldDataContainer != null) {
                alpacaJsonData.add(fieldNameDataContainer, cronoprogrammaArray);
            }
        }
    }
    return alpacaJsonData;
}

