5141	    public AccountDto getEmailAccountByBando(Bando bando) {
5142	        try {
5143	            AccountDto emailAccount = null;
5144	            if (bando.isMailEnabled()) {
5145	                emailAccount = new AccountDto();
5146	                KeystoreCryptoUtilProps keystoreUtil = new KeystoreCryptoUtilProps();
5147	                String passwordDec = keystoreUtil.decrypt(bando.getMailPassword());
5148	
5149	                emailAccount = new AccountDto();
5150	                emailAccount.setHost(bando.getMailHost());
5151	                emailAccount.setPort(bando.getMailPort());
5152	                emailAccount.setProtocol(bando.getMailProtocol());
5153	                emailAccount.setUsername(bando.getMailUsername());
5154	                emailAccount.setPassword(passwordDec);
5155	                emailAccount.setSocketPort(bando.getMailSocketFactoryPort());
5156	                emailAccount.setAuth(String.valueOf(bando.getMailAuth()));
5157	                emailAccount.setStarttls(bando.getMailStartTlsEnabled());
5158	                emailAccount.setDebug(bando.getMailDebug());
5159	                emailAccount.setStarttlsRequired(bando.getMailStartTlsRequired());
5160	                emailAccount.setSocketFactoryFallback(bando.getMailSocketFactoryPortFallback());
5161	                emailAccount.setFrom(bando.getMailFrom());
5162	                emailAccount.setSslProtocols(bando.getMailProtocols());
5163	            }
5164	            return emailAccount;
5165	        } catch (Exception e) {
5166	            throw new RuntimeException(e);
5167	        }
5168	    }
