public AccountDto getEmailAccountByBando(Bando bando) {
    try {
        AccountDto emailAccount = null;
        if (bando.isMailEnabled()) {
            emailAccount = new AccountDto();
            KeystoreCryptoUtilProps keystoreUtil = new KeystoreCryptoUtilProps();
            String passwordDec = keystoreUtil.decrypt(bando.getMailPassword());

            emailAccount = new AccountDto();
            emailAccount.setHost(bando.getMailHost());
            emailAccount.setPort(bando.getMailPort());
            emailAccount.setProtocol(bando.getMailProtocol());
            emailAccount.setUsername(bando.getMailUsername());
            emailAccount.setPassword(passwordDec);
            emailAccount.setSocketPort(bando.getMailSocketFactoryPort());
            emailAccount.setAuth(String.valueOf(bando.getMailAuth()));
            emailAccount.setStarttls(bando.getMailStartTlsEnabled());
            emailAccount.setDebug(bando.getMailDebug());
            emailAccount.setStarttlsRequired(bando.getMailStartTlsRequired());
            emailAccount.setSocketFactoryFallback(bando.getMailSocketFactoryPortFallback());
            emailAccount.setFrom(bando.getMailFrom());
            emailAccount.setSslProtocols(bando.getMailProtocols());
        }
        return emailAccount;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

public void addDatiAggiuntiviFormDomandaBando(IstanzaDomandaBando istanzaDomandaBando, Long userId, Long companyId,
                                              String username, Long groupId) throws Exception {
    String istanzaJson = istanzaDomandaBando.getJson();
    DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
    List<DatoAggiuntivoChiaveDTO> chiavi = getDatiAggiuntiviChiavi(domandaBando.getBandoId());

    Configuration configuration = Configuration.defaultConfiguration().addOptions(Option.SUPPRESS_EXCEPTIONS);
    DocumentContext document = JsonPath.using(configuration).parse(istanzaJson);
    if (Validator.isNotNull(chiavi) && !chiavi.isEmpty()) {
        for (DatoAggiuntivoChiaveDTO chiave : chiavi) {

            if (Validator.isNotNull(chiave.getDataJsonPath())) {
                Object value = document.read(chiave.getDataJsonPath());
                if (Validator.isNotNull(value)) {
                    if (chiave.isRipetibile()) {
                        Gson gson = new Gson();
                        JsonArray jsonArray = new JsonParser().parse(value.toString()).getAsJsonArray();
                        for (int i=0; i< jsonArray.size(); i++) {
                            DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                    .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                            JsonObject jsonObject = jsonArray.get(i).getAsJsonObject();
                            String valore = "";
                            if (Validator.isNotNull(jsonObject) && jsonObject.has("datiMandanti")) {
                                JsonObject datiMandanti = jsonObject.get("datiMandanti").getAsJsonObject();
                                if (Validator.isNotNull(datiMandanti) && datiMandanti.has("nomePartner")) {
                                    valore = datiMandanti.get("nomePartner").getAsString();
                                }
                            }
                            domandaBandoDatoAggiuntivo.setChiave(chiave.getName());

                            domandaBandoDatoAggiuntivo.setValore(valore);
                            domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                            domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                            domandaBandoDatoAggiuntivo.setUserId(userId);
                            domandaBandoDatoAggiuntivo.setUserName(username);
                            domandaBandoDatoAggiuntivo.setGroupId(groupId);
                            domandaBandoDatoAggiuntivoLocalService
                                    .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                        }

                    } else {
                        DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                        domandaBandoDatoAggiuntivo.setChiave(chiave.getName());
                        domandaBandoDatoAggiuntivo.setValore(String.valueOf(value));
                        domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                        domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                        domandaBandoDatoAggiuntivo.setUserId(userId);
                        domandaBandoDatoAggiuntivo.setUserName(username);
                        domandaBandoDatoAggiuntivo.setGroupId(groupId);
                        domandaBandoDatoAggiuntivoLocalService
                                .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                    }
                }
            }
        }
    }
}

