public void addDatiAggiuntiviDomandaBando(IstanzaDomandaBando istanzaDomandaBando, Long userId, Long companyId,
                                          String username, Long groupId) throws Exception {
    String istanzaJson = istanzaDomandaBando.getJson();
    DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
    List<DatoAggiuntivoChiave> chiavi = getDatiAggiuntiviChiaviDaForm(domandaBando.getBandoId());

    Configuration configuration = Configuration.defaultConfiguration().addOptions(Option.SUPPRESS_EXCEPTIONS);
    DocumentContext document = JsonPath.using(configuration).parse(istanzaJson);
    if (Validator.isNotNull(chiavi) && !chiavi.isEmpty()) {
        for (DatoAggiuntivoChiave chiave : chiavi) {

            if (Validator.isNotNull(chiave.getDataJsonPath())) {
                if (chiave.equals(DatoAggiuntivoChiave.FORM_ESECUZIONE_NON_ABILITATO)) {
                    Object value = document.read(chiave.getDataJsonPath());
                    if (Validator.isNotNull(value)) {
                        List<String> values = List.of(value.toString().split("\\|"));
                        if (Validator.isNotNull(values) && !values.isEmpty()) {
                            for (String valore : values) {
                                if (Validator.isNotNull(valore)) {
                                    DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                            .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                    domandaBandoDatoAggiuntivo.setChiave(chiave.name());
                                    domandaBandoDatoAggiuntivo.setValore(valore);
                                    domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                                    domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                                    domandaBandoDatoAggiuntivo.setUserId(userId);
                                    domandaBandoDatoAggiuntivo.setUserName(username);
                                    domandaBandoDatoAggiuntivo.setGroupId(groupId);
                                    domandaBandoDatoAggiuntivoLocalService
                                            .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                                }
                            }
                        }
                    }
                } else {
                    Object value = document.read(chiave.getDataJsonPath());
                    if (Validator.isNotNull(value)) {
                        DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                        domandaBandoDatoAggiuntivo.setChiave(chiave.name());
                        domandaBandoDatoAggiuntivo.setValore(String.valueOf(value));
                        domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                        domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                        domandaBandoDatoAggiuntivo.setUserId(userId);
                        domandaBandoDatoAggiuntivo.setUserName(username);
                        domandaBandoDatoAggiuntivo.setGroupId(groupId);
                        domandaBandoDatoAggiuntivoLocalService
                                .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                    }
                }
            }

        }
        if (!chiavi.contains(DatoAggiuntivoChiave.PROVINCIA_SEDE_LEGALE_ENTE)) {
            Object value = document.read(PROVINCIA_SEDE_LEGALE_ENTE_ALTERNATIVA);
            if (Validator.isNotNull(value)) {
                DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                        .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                domandaBandoDatoAggiuntivo.setChiave(DatoAggiuntivoChiave.PROVINCIA_SEDE_LEGALE_ENTE.name());
                domandaBandoDatoAggiuntivo.setValore(String.valueOf(value));
                domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                domandaBandoDatoAggiuntivo.setUserId(userId);
                domandaBandoDatoAggiuntivo.setUserName(username);
                domandaBandoDatoAggiuntivo.setGroupId(groupId);
                domandaBandoDatoAggiuntivoLocalService
                        .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
            }
        }
    }

    // Recupero dinamico dati aggiuntivi dai campi con attributo "datoAggiuntivo" nelle options
    try {
        JsonObject jsonRoot = new JsonParser().parse(istanzaJson).getAsJsonObject();
        JsonObject alpacaObj = jsonRoot.getAsJsonObject("alpaca");

        if (alpacaObj != null && alpacaObj.has("options") && alpacaObj.has("data")) {
            JsonObject optionsObj = alpacaObj.getAsJsonObject("options");
            JsonObject dataObj = alpacaObj.getAsJsonObject("data");

            if (optionsObj.has("fields") && optionsObj.get("fields").isJsonObject()) {
                JsonObject optionsFields = optionsObj.getAsJsonObject("fields");
                Map<String, String> datiAggiuntiviDinamici = new LinkedHashMap<>();
                Map<String, List<String>> datiAggiuntiviDinamiciArray = new LinkedHashMap<>();
                _trovaDatiAggiuntiviDaOptions(optionsFields, dataObj, datiAggiuntiviDinamici, datiAggiuntiviDinamiciArray);

                for (Map.Entry<String, String> entry : datiAggiuntiviDinamici.entrySet()) {
                    String chiaveDinamica = entry.getKey();
                    String valoreDinamico = entry.getValue();

                    if (Validator.isNotNull(chiaveDinamica) && Validator.isNotNull(valoreDinamico)) {
                        long count = domandaBandoDatoAggiuntivoLocalService
                                .countDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                                        domandaBando.getDomandaBandoId(), Collections.singletonList(chiaveDinamica));

                        if (count == 0) {
                            DomandaBandoDatoAggiuntivo dato = domandaBandoDatoAggiuntivoLocalService
                                    .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                            dato.setChiave(chiaveDinamica);
                            dato.setValore(valoreDinamico);
                            dato.setDomandaBandoId(domandaBando.getDomandaBandoId());
                            dato.setCompanyId(companyId);
                            dato.setUserId(userId);
                            dato.setUserName(username);
                            dato.setGroupId(groupId);
                            domandaBandoDatoAggiuntivoLocalService.updateDomandaBandoDatoAggiuntivo(dato);
                        }
                    }
                }

                // Gestione dati aggiuntivi di tipo array
                for (Map.Entry<String, List<String>> entry : datiAggiuntiviDinamiciArray.entrySet()) {
                    String chiaveDinamica = entry.getKey();
                    List<String> valoriDinamici = entry.getValue();

                    if (Validator.isNotNull(chiaveDinamica) && valoriDinamici != null && !valoriDinamici.isEmpty()) {
                        long count = domandaBandoDatoAggiuntivoLocalService
                                .countDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                                        domandaBando.getDomandaBandoId(), Collections.singletonList(chiaveDinamica));

                        if (count == 0) {
                            for (String valoreDinamico : valoriDinamici) {
                                if (Validator.isNotNull(valoreDinamico)) {
                                    DomandaBandoDatoAggiuntivo dato = domandaBandoDatoAggiuntivoLocalService
                                            .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                    dato.setChiave(chiaveDinamica);
                                    dato.setValore(valoreDinamico);
                                    dato.setDomandaBandoId(domandaBando.getDomandaBandoId());
                                    dato.setCompanyId(companyId);
                                    dato.setUserId(userId);
                                    dato.setUserName(username);
                                    dato.setGroupId(groupId);
                                    domandaBandoDatoAggiuntivoLocalService.addDomandaBandoDatoAggiuntivo(dato);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    catch (Exception e) {
        log.error("Errore nel recupero dati aggiuntivi da attributo datoAggiuntivo nelle options: " + e.getMessage(), e);
    }
}

